INSERT INTO `attestations` (`id`,`form_id`,`source_id`,`date_label`,`year`,`witness`,`locator`,`excerpt`,`confidence`,`witness_type`,`repository`,`shelfmark`,`facsimile_url`,`directly_inspected`,`editorial_note`) VALUES
(102,205,100,'1704',1704,'A bibliographic note in John Harris’s Lexicon technicum names December while pointing readers to the December 1682 Acta Eruditorum.','Image [816], left column, note above TANGENT; e-rara content image 2867880','In the Acta Eruditorum for December, 1682. there is an Universal Method for drawing Tangents to all Curves','established','printed_book','ETH-Bibliothek Zürich','Rar 98 Ex.A GF, content image 2867880','https://www.e-rara.ch/zut/content/zoom/2867880?query=DECEMBER',1,'The e-rara page image was directly inspected. It verifies a contextual 1704 use of December as a month name; it is not a DECEMBER headword, is not claimed as the earliest English occurrence, and does not prove the Roman tenth-to-twelfth-month history or deeper ancestry.'),
(103,294,100,'1704',1704,'John Harris’s NOTES in Musick entry describes a fixed group of six select syllables formerly used to distinguish degrees of sound.','Image [572], left column, NOTES in Musick entry; e-rara content image 2867636','six select Syllables were formerly used to that purpose, ascending and descending in order, viz. Ut, Re, Mi, Fa, Sol, La','established','printed_book','ETH-Bibliothek Zürich','Rar 98 Ex.A GF, content image 2867636','https://www.e-rara.ch/zut/content/zoom/2867636?query=SELECT',1,'The e-rara page image was directly inspected. It verifies a contextual 1704 adjectival use of select for a specially chosen set of syllables; it is not a SELECT headword, is not claimed as the earliest occurrence, and does not prove the Latin morphology or reconstructed ancestry.'),
(104,60,100,'1704',1704,'John Harris’s FEE-FARM entry uses Legal to mark the specifically legal sense of the term.','Image [333], left column, FEE-FARM entry; e-rara content image 2867397','FEE-FARM, in a Legal Sense signifies Land held of another in Fee','established','printed_book','ETH-Bibliothek Zürich','Rar 98 Ex.A GF, content image 2867397','https://www.e-rara.ch/zut/content/zoom/2867397?query=LEGAL',1,'The e-rara page image was directly inspected. It verifies a contextual 1704 use of Legal meaning related to law; it is not a LEGAL headword, is not claimed as the earliest occurrence, and does not prove the Latin lex family or any disputed deeper reconstruction.'),
(105,211,100,'1704',1704,'A tide passage in John Harris’s Lexicon technicum uses check as a verb meaning restrain or impede.','Image [834], left column, tide explanation; e-rara content image 2867898','if the Tide coming about the Island from the North did not check it','established','printed_book','ETH-Bibliothek Zürich','Rar 98 Ex.A GF, content image 2867898','https://www.e-rara.ch/zut/content/zoom/2867898?query=CHECK',1,'The e-rara page image was directly inspected. It verifies a contextual 1704 verbal use of check in the restrain-or-impede sense; it is not a CHECK headword, is not claimed as the earliest occurrence, and does not establish the later verify sense, banking senses, or Persian chess ancestry.');
